const lt64=(n,d,sh)=>({lv:`1964. gada lietuviešu vārdu kalendārā ${n} ierakstīts ${d[0]}${sh?` ar īsformu ${sh}`:''}.`,ru:`В литовском календаре имён 1964 года ${n} записан на ${d[1]}${sh?` с краткой формой ${sh}`:''}.`,en:`The Lithuanian name calendar of 1964 lists ${n} on ${d[2]}${sh?`, with the short form ${sh}`:''}.`,lt:`1964 metų lietuvių vardų kalendoriuje ${n} įrašytas ${d[3]}${sh?` su trumpiniu ${sh}`:''}.`,et:`1964. aasta leedu nimekalendris on ${n} ${d[4]}${sh?` lühikujuga ${sh}`:''}.`});
