const eva={lv:'Ievas (Eva) saimei, kas cēlusies no ebreju Ḥawwā — «dzīvība, dzīvības devēja»',ru:'семье имени Ева (Eva), восходящей к древнееврейскому Ḥawwā — «жизнь, дающая жизнь»',en:'the Eva family, from Hebrew Ḥawwā, “life, giver of life”',lt:'Ievos (Eva) šeimai, kilusiai iš hebrajų Ḥawwā – „gyvybė, gyvybės davėja“',et:'Eva nimeperre, mis pärineb heebrea nimest Ḥawwā, „elu, elu andja“'};
const joa={lv:'Joahima saimei. Ebreju vārda pamatā ir doma «Dievs paceļ, nostiprina»',ru:'семье имени Иоаким. В основе еврейского имени — мысль «Бог возвышает, утверждает»',en:'the Joahims (Joachim) family. The Hebrew name is explained as “God raises up, establishes”',lt:'Joachimo šeimai. Hebrajiško vardo pagrindas – mintis „Dievas pakelia, įtvirtina“',et:'Joachimi nimeperre. Heebrea nime seletatakse kui „Jumal tõstab, kinnitab“'};
const barb={lv:'Barbaras saimei, kas cēlusies no grieķu barbaros — «svešinieks, citā valodā runājošs»; sieviešu vārdā to parasti tulko «svešzemniece»',ru:'семье имени Варвара (Barbara), от греческого barbaros — «чужеземец, говорящий на другом языке»; в женском имени его обычно передают как «чужестранка»',en:'the Barbara family, from Greek barbaros, “foreigner, speaker of another language”; in the feminine name it is usually rendered “foreign woman”',lt:'Barboros šeimai, kilusiai iš graikų barbaros – „svetimšalis, kalbantis kita kalba“; moteriškame varde jis paprastai verčiamas „svetimšalė“',et:'Barbara nimeperre, mis pärineb kreeka sõnast barbaros, „võõramaalane, teise keele kõneleja“; naisenimes tõlgitakse seda tavaliselt „võõramaa naine“'};
const sab={lv:'Vārda saime cēlusies no latīņu Sabina — vārda Sabinus sieviešu formas; tā apzīmēja sabīņus, seno Itālijas tautu.',ru:'Семья имени восходит к латинскому Sabina — женской форме имени Sabinus; так называли сабинян, древний народ Италии.',en:'The family goes back to Latin Sabina, the feminine of Sabinus, which referred to the Sabines, a people of ancient Italy.',lt:'Vardų šeima kilusi iš lotynų Sabina – vardo Sabinus moteriškosios formos; taip vadinti sabinai, senovės Italijos tauta.',et:'Nimepere pärineb ladina nimest Sabina, nime Sabinus naisvormist, mis tähistas sabiine, Vana-Itaalia rahvast.'};
const sabr={lv:'Sabrina saistīta ar Severnas upi: latīņu Sabrina atbilst velsiešu Habren; upes nosaukuma tālākā nozīme nav droši zināma. Stāsti par upes princesi Sabrinu ir leģendas.',ru:'Sabrina связана с рекой Северн: латинское Sabrina соответствует валлийскому Habren; дальнейшее значение названия реки неясно. Рассказы о речной принцессе Сабрине — легенды.',en:'Sabrina is linked with the River Severn: Latin Sabrina corresponds to Welsh Habren, and the river name’s further meaning is not securely known. Stories of a river princess Sabrina are legends.',lt:'Sabrina siejama su Severno upe: lotynų Sabrina atitinka valų Habren; tolesnė upėvardžio reikšmė neaiški. Pasakojimai apie upės princesę Sabriną – legendos.',et:'Sabrina seostub Severni jõega: ladina Sabrina vastab kõmri Habrenile ning jõenime edasine tähendus pole kindlalt teada. Lood jõeprintsess Sabrinast on legendid.'};
const nik={lv:'Tas pieder Nikolaja (Nikolaos) saimei: grieķu nikē — «uzvara» — un laos — «tauta».',ru:'Оно относится к семье имени Николай (Nikolaos): греческие nikē — «победа» — и laos — «народ».',en:'It belongs to the Nikolaos/Nikolajs family: Greek nikē, “victory”, and laos, “people”.',lt:'Jis priklauso Mikalojaus (Nikolaos) šeimai: graikų nikē – „pergalė“ – ir laos – „tauta“.',et:'See kuulub Nikolaose nimeperre: kreeka nikē, „võit“, ja laos, „rahvas“.'};

export const plainCalendar1202={
 lv:{
  Sņežana:E(`Sņežana ir horvātu Snježana latviskā forma. Šī dienvidslāvu vārdu saime cēlusies no snežan — «sniegots», no vārda «sniegs».`,`Sņežana — латышская форма хорватского Snježana. Эта южнославянская семья имён происходит от snežan — «снежный», от слова «снег».`,`Sņežana is the Latvian form of Croatian Snježana. This South Slavic name family comes from snežan, “snowy”, from the word for snow.`,`Sņežana – latviška kroatiško Snježana forma. Ši pietų slavų vardų šeima kilusi iš snežan – „snieguotas“, nuo žodžio „sniegas“.`,`Sņežana on horvaadi nime Snježana läti vorm. See lõunaslaavi nimepere pärineb sõnast snežan, „lumine“, sõnast „lumi“.`),
  Evija:E(`Evija pieder ${eva.lv}. ¶ Evija Gulbe 2011. gadā izdeva grāmatu «Koko un Riko»; tēlu piedzīvojumi turpinājās citās grāmatās, un 2017. gada 10. septembrī Latvijas Leļļu teātrī notika Ģirta Šoļa iestudējuma «Koko un Riko» pirmizrāde.`,`Evija относится к ${eva.ru}. ¶ Эвия Гулбе в 2011 году выпустила книгу «Koko un Riko»; приключения героев продолжились в других книгах, а 10 сентября 2017 года в Латвийском театре кукол прошла премьера постановки Гиртса Шолиса «Koko un Riko».`,`Evija belongs to ${eva.en}. ¶ Evija Gulbe published Koko un Riko in 2011; the characters’ adventures continued in further books, and Ģirts Šolis’s stage version premiered at the Latvian Puppet Theatre on 10 September 2017.`,`Evija priklauso ${eva.lt}. ¶ Evija Gulbe 2011 metais išleido knygą „Koko un Riko“; veikėjų nuotykiai tęsėsi kitose knygose, o 2017 metų rugsėjo 10 dieną Latvijos lėlių teatre įvyko Ģirto Šolio spektaklio „Koko un Riko“ premjera.`,`Evija kuulub ${eva.et}. ¶ Evija Gulbe avaldas 2011. aastal raamatu „Koko un Riko“; tegelaste seiklused jätkusid teistes raamatutes ning 10. septembril 2017 esietendus Läti Nukuteatris Ģirts Šolise lavastus „Koko un Riko“.`),
  Ēvija:E(`Ēvija ir zviedru Evy latviskā forma ar garo ē; Evy ir Evas vai Evelīnas mīlināmā forma. Norvēģu Evy latviski atveido ar īso e — Evija.`,`Ēvija — латышская форма шведского Evy с долгим ē; Evy — ласкательная форма имён Eva или Evelina. Норвежское Evy по-латышски передают с кратким e — Evija.`,`Ēvija is the Latvian form of Swedish Evy, with a long ē; Evy is a pet form of Eva or Evelina. Norwegian Evy is rendered with a short e, Evija.`,`Ēvija – latviška švediško Evy forma su ilgąja ē; Evy – maloninė vardų Eva arba Evelina forma. Norvegiškas Evy latviškai perteikiamas su trumpąja e – Evija.`,`Ēvija on rootsi nime Evy läti vorm pika ē-ga; Evy on nime Eva või Evelina hellitusvorm. Norra Evy antakse läti keeles edasi lühikese e-ga – Evija.`),
  Evijs:E(`Evijs ir vīriešu vārds, ko saista ar Eviju un Evu. Eva cēlusies no ebreju Ḥawwā — «dzīvība, dzīvības devēja». ¶ Rīgā Evijs pierakstīts 1971. gadā.`,`Evijs — мужское имя, связанное с Evija и Eva. Eva восходит к древнееврейскому Ḥawwā — «жизнь, дающая жизнь». ¶ В Риге Evijs записан в 1971 году.`,`Evijs is a masculine name linked with Evija and Eva. Eva goes back to Hebrew Ḥawwā, “life, giver of life”. ¶ It is recorded in Riga in 1971.`,`Evijs – vyriškas vardas, siejamas su Evija ir Eva. Eva kilusi iš hebrajų Ḥawwā – „gyvybė, gyvybės davėja“. ¶ Rygoje Evijs užrašytas 1971 metais.`,`Evijs on mehenimi, mis seostub nimedega Evija ja Eva. Eva pärineb heebrea nimest Ḥawwā, „elu, elu andja“. ¶ Riias on Evijs kirja pandud 1971. aastal.`),
  Evika:E(`Evika pieder Evijas un Evas saimei. Eva cēlusies no ebreju Ḥawwā — «dzīvība, dzīvības devēja». ¶ Talsu rajonā Evika pierakstīta 1973. gadā.`,`Evika относится к семье имён Evija и Eva. Eva восходит к древнееврейскому Ḥawwā — «жизнь, дающая жизнь». ¶ В Талсинском районе Evika записана в 1973 году.`,`Evika belongs to the Evija and Eva family. Eva goes back to Hebrew Ḥawwā, “life, giver of life”. ¶ It is recorded in Talsi district in 1973.`,`Evika priklauso Evijos ir Evos šeimai. Eva kilusi iš hebrajų Ḥawwā – „gyvybė, gyvybės davėja“. ¶ Talsų rajone Evika užrašyta 1973 metais.`,`Evika kuulub Evija ja Eva nimeperre. Eva pärineb heebrea nimest Ḥawwā, „elu, elu andja“. ¶ Talsi rajoonis on Evika kirja pandud 1973. aastal.`),
  Evisa:E(`Evisa pieder Evijas un Evas saimei. Eva cēlusies no ebreju Ḥawwā — «dzīvība, dzīvības devēja». ¶ Mērsragā Evisa pierakstīta 1971. gadā.`,`Evisa относится к семье имён Evija и Eva. Eva восходит к древнееврейскому Ḥawwā — «жизнь, дающая жизнь». ¶ В Мерсрагсе Evisa записана в 1971 году.`,`Evisa belongs to the Evija and Eva family. Eva goes back to Hebrew Ḥawwā, “life, giver of life”. ¶ It is recorded in Mērsrags in 1971.`,`Evisa priklauso Evijos ir Evos šeimai. Eva kilusi iš hebrajų Ḥawwā – „gyvybė, gyvybės davėja“. ¶ Mėrsrage Evisa užrašyta 1971 metais.`,`Evisa kuulub Evija ja Eva nimeperre. Eva pärineb heebrea nimest Ḥawwā, „elu, elu andja“. ¶ Mērsragsis on Evisa kirja pandud 1971. aastal.`),
  Raita:E(`Raita saistīta ar latviešu īpašības vārdu raits — «ātrs, veikls, žirgts», ko saka arī par darbu, kas veicas, un par strauji tekošu strautu. Vīriešu vārds Raitis tiek saistīts ar Raitu; somu Raita un raitis («svaigs, tīrs») ir tikai atsevišķs salīdzinājums. ¶ Neparasti, ka vīriešu forma kalendārā nonāca pirmā: Raitis kalendārā ir kopš 1927. gada un Valmierā pierakstīts 1938. gadā, bet Raita kalendārā ir kopš 1932. gada un Raunā pierakstīta 1935. gadā. Abi gadi attiecas uz neatkarīgās Latvijas starpkaru laiku.`,`Raita связана с латышским прилагательным raits — «быстрый, ловкий, бойкий»; так говорят и о спорящейся работе, и о быстром ручье. Мужское Raitis связывают с Raita; финские Raita и raitis («свежий, чистый») — лишь отдельное сравнение. ¶ Необычно, что мужская форма попала в календарь первой: Raitis в календаре с 1927 года и записан в Валмиере в 1938 году, а Raita в календаре с 1932 года и записана в Рауне в 1935 году. Оба года приходятся на межвоенную независимую Латвию.`,`Raita is linked with the Latvian adjective raits, “quick, nimble, brisk”, also said of work that goes smoothly and of a fast stream. The masculine Raitis is linked with Raita; Finnish Raita and raitis (“fresh, clean”) are only a separate comparison. ¶ Unusually, the masculine form reached the calendar first: Raitis has been in the calendar since 1927 and is recorded in Valmiera in 1938, while Raita has been in the calendar since 1932 and is recorded in Rauna in 1935. Both years fall in the interwar years of independent Latvia.`,`Raita siejama su latvių būdvardžiu raits – „greitas, vikrus, žvalus“; taip sakoma ir apie sklandų darbą, ir apie sraunų upelį. Vyriškas Raitis siejamas su Raita; suomiški Raita ir raitis („šviežias, švarus“) – tik atskiras palyginimas. ¶ Neįprasta, kad vyriškoji forma į kalendorių pateko pirmoji: Raitis kalendoriuje yra nuo 1927 metų ir Valmieroje užrašytas 1938 metais, o Raita kalendoriuje yra nuo 1932 metų ir Raunoje užrašyta 1935 metais. Abu metai patenka į tarpukario nepriklausomą Latviją.`,`Raita seostub läti omadussõnaga raits, „kiire, nobe, reibas“, mida öeldakse ka libedalt edeneva töö ja kiirevoolulise oja kohta. Mehenimi Raitis seostub nimega Raita; soome Raita ja raitis („värske, puhas“) on vaid eraldi võrdlus. ¶ Haruldaselt jõudis kalendrisse esimesena mehenimi: Raitis on kalendris alates 1927. aastast ja kirja pandud Valmieras 1938. aastal, Raita on kalendris alates 1932. aastast ja kirja pandud Raunas 1935. aastal. Mõlemad aastad jäävad sõdadevahelisse iseseisvasse Lätti.`),
  Jogita:E(`Jogita ir latviešu sieviešu vārds ar nenoskaidrotu izcelsmi; iespējama, bet apšaubīta ir saikne ar Jogints. ¶ Jogita pierakstīta 1922. gadā, kā arī 1973. un 1975. gadā; kalendārā tā ir kopš 1964. gada.`,`Jogita — латышское женское имя неясного происхождения; возможна, но сомнительна связь с Jogints. ¶ Jogita записана в 1922 году, а также в 1973 и 1975 годах; в календаре — с 1964 года.`,`Jogita is a Latvian feminine name of unsettled origin; a link with Jogints is possible but doubtful. ¶ It is recorded in 1922 and again in 1973 and 1975, and has been in the calendar since 1964.`,`Jogita – latviškas moteriškas vardas neaiškios kilmės; galimas, bet abejotinas ryšys su Jogints. ¶ Jogita užrašyta 1922 metais, taip pat 1973 ir 1975 metais; kalendoriuje ji yra nuo 1964 metų.`,`Jogita on ebaselge päritoluga läti naisenimi; seos nimega Jogints on võimalik, kuid kaheldav. ¶ Jogita on kirja pandud 1922. aastal ning ka 1973. ja 1975. aastal; kalendris on see alates 1964. aastast.`),
  Akims:E(`Akims salīdzināms ar krievu Akim — Joahima formu; Joahims saistīts ar Bībeles vārdiem Jojahins jeb Jojakims. ¶ Londonas Nacionālās galerijas ap 1400. gadu gleznotā panelī Joahims un Anna satiekas pie Jeruzalemes Zelta vārtiem — ainas pamatā ir Zelta leģendas stāsts par Marijas vecākiem.`,`Akims сравнивают с русским Аким — формой имени Иоаким; Иоаким связан с библейскими именами Иехония, или Иоаким. ¶ На панели около 1400 года из лондонской Национальной галереи Иоаким и Анна встречаются у Золотых ворот Иерусалима — сцена восходит к «Золотой легенде» о родителях Марии.`,`Akims is compared with Russian Akim, a form of Joachim, which is linked with the biblical names Jehoiachin or Jehoiakim. ¶ On a panel painted around 1400, now in London’s National Gallery, Joachim and Anne meet at Jerusalem’s Golden Gate, a scene from the Golden Legend’s story of Mary’s parents.`,`Akims lyginamas su rusišku Akim – Joachimo forma; Joachimas siejamas su bibliniais vardais Jehojachinas arba Jehojakimas. ¶ Londono Nacionalinės galerijos apie 1400 metus tapytame paveiksle Joachimas ir Ona susitinka prie Jeruzalės Auksinių vartų – scena paimta iš „Aukso legendos“ pasakojimo apie Marijos tėvus.`,`Akims on võrreldav vene nimega Akim, mis on Joachimi vorm; Joachim seostub piiblinimedega Jojakin või Jojakim. ¶ Umbes 1400. aastal maalitud tahvlil Londoni Rahvusgaleriis kohtuvad Joachim ja Anna Jeruusalemma Kuldvärava juures – stseen pärineb „Kuldlegendi“ loost Maarja vanematest.`),
  Ako:E(`Ako ir viens no līvu vārdiem, kas zināmi no Indriķa hronikas; to uzskata par iespējamu mīlināmo formu ar -o, bet sakne un nozīme nav zināma. Igauņu Ako kalendārā parādījās jau 1845. gadā un tur saistīts ar Ago — Agatona vai Augusta īsformu —, tāpēc iespējams arī mūsdienu ceļš no Igaunijas. ¶ Hronika min līvu vadoni Ako, kurš 1206. gadā krita līvu pretestībā pie Salaspils; viņa galvu ar uzvaras ziņu nosūtīja bīskapam.`,`Ako — одно из ливских имён, известных из Хроники Генриха Латвийского; его считают возможной уменьшительной формой на -o, но корень и значение неизвестны. Эстонское Ako появилось в календаре уже в 1845 году и связано там с Ago — краткой формой Агафона или Августа, поэтому возможен и современный путь из Эстонии. ¶ Хроника называет ливского вождя Ако, павшего в 1206 году во время сопротивления ливов у Саласпилса; его голову вместе с вестью о победе отправили епископу.`,`Ako is one of the Livonian names known from the Chronicle of Henry of Livonia; it is seen as a possible pet form in -o, but its root and meaning are unknown. Estonian Ako appeared in a calendar as early as 1845, linked there with Ago, a short form of Agathon or August, so a modern route from Estonia is also possible. ¶ The chronicle names the Livonian leader Ako, who fell in 1206 during the Livonian resistance at Salaspils; his head was sent to the bishop with the news of victory.`,`Ako – vienas lyvių vardų, žinomų iš Henriko Latvio kronikos; jis laikomas galima malonine forma su -o, bet šaknis ir reikšmė nežinomos. Estiškas Ako kalendoriuje pasirodė jau 1845 metais ir ten siejamas su Ago – Agatono arba Augusto trumpiniu, todėl galimas ir šiuolaikinis kelias iš Estijos. ¶ Kronika mini lyvių vadą Aką, žuvusį 1206 metais per lyvių pasipriešinimą prie Salaspilio; jo galva su žinia apie pergalę buvo nusiųsta vyskupui.`,`Ako on üks Läti Henriku kroonikast tuntud liivi nimesid; seda peetakse võimalikuks -o-liiteliseks hellitusvormiks, kuid tüvi ja tähendus pole teada. Eesti Ako ilmus kalendrisse juba 1845. aastal ja seostub seal nimega Ago – Agathoni või Augusti lühikujuga –, nii et võimalik on ka uusaegne tee Eestist. ¶ Kroonika nimetab liivi pealikku Akot, kes langes 1206. aastal liivlaste vastupanus Salaspilsi juures; tema pea saadeti võiduteatega piiskopile.`),
  Jakims:E(`Jakims pieder ${joa.lv}. ¶ Viļakā Jakims pierakstīts 1636. gadā.`,`Jakims относится к ${joa.ru}. ¶ В Виляке Jakims записан в 1636 году.`,`Jakims belongs to ${joa.en}. ¶ It is recorded in Viļaka in 1636.`,`Jakims priklauso ${joa.lt}. ¶ Viliakoje Jakims užrašytas 1636 metais.`,`Jakims kuulub ${joa.et}. ¶ Viļakas on Jakims kirja pandud 1636. aastal.`),
  Joahims:E(`Joahims pieder ${joa.lv}. ¶ Koknesē Joahims pierakstīts 1599. gadā, kalendārā tas ir kopš 1767. gada.`,`Joahims относится к ${joa.ru}. ¶ В Кокнесе Joahims записан в 1599 году, в календаре — с 1767 года.`,`Joahims belongs to ${joa.en}. ¶ It is recorded in Koknese in 1599 and has been in the calendar since 1767.`,`Joahims priklauso ${joa.lt}. ¶ Koknesėje Joahims užrašytas 1599 metais, kalendoriuje jis yra nuo 1767 metų.`,`Joahims kuulub ${joa.et}. ¶ Koknesesis on Joahims kirja pandud 1599. aastal, kalendris on see alates 1767. aastast.`),
  Joakims:E(`Joakims ir vārda Joahims forma. Tas ir ebreju teoforisks vārds ar nozīmēm «Jahve paceļ», «Jahve modina». Rēzeknē Joakims pierakstīts 1877. gadā, kalendārā tas ir kopš 1899. gada. ¶ Londonas Nacionālās galerijas ap 1400. gadu gleznotā panelī Joahims un Anna satiekas pie Jeruzalemes Zelta vārtiem — ainas pamatā ir Zelta leģendas stāsts par Marijas vecākiem.`,`Joakims — форма имени Joahims. Это еврейское теофорное имя со значениями «Яхве возвышает», «Яхве пробуждает». В Резекне Joakims записан в 1877 году, в календаре — с 1899 года. ¶ На панели около 1400 года из лондонской Национальной галереи Иоаким и Анна встречаются у Золотых ворот Иерусалима — сцена восходит к «Золотой легенде» о родителях Марии.`,`Joakims is a form of Joahims, a Hebrew name containing God’s name, with meanings such as “Yahweh raises” and “Yahweh awakens”. It is recorded in Rēzekne in 1877 and has been in the calendar since 1899. ¶ On a panel painted around 1400, now in London’s National Gallery, Joachim and Anne meet at Jerusalem’s Golden Gate, a scene from the Golden Legend’s story of Mary’s parents.`,`Joakims – vardo Joahims forma; tai hebrajiškas vardas su Dievo vardu, reiškiantis „Jahvė pakelia“, „Jahvė pažadina“. Rėzeknėje Joakims užrašytas 1877 metais, kalendoriuje jis yra nuo 1899 metų. ¶ Londono Nacionalinės galerijos apie 1400 metus tapytame paveiksle Joachimas ir Ona susitinka prie Jeruzalės Auksinių vartų – scena paimta iš „Aukso legendos“ pasakojimo apie Marijos tėvus.`,`Joakims on nime Joahims vorm, Jumala nime sisaldav heebrea nimi tähendustega „Jahve tõstab“, „Jahve äratab“. Rēzeknes on Joakims kirja pandud 1877. aastal, kalendris on see alates 1899. aastast. ¶ Umbes 1400. aastal maalitud tahvlil Londoni Rahvusgaleriis kohtuvad Joachim ja Anna Jeruusalemma Kuldvärava juures – stseen pärineb „Kuldlegendi“ loost Maarja vanematest.`),
  Jukums:E(`Jukums pieder ${joa.lv}. ¶ Grobiņā Jukums pierakstīts 1598. gadā; vārdu grupa Jukums/Joahims kalendārā ir kopš 1767. gada.`,`Jukums относится к ${joa.ru}. ¶ В Гробине Jukums записан в 1598 году; пара Jukums/Joahims в календаре с 1767 года.`,`Jukums belongs to ${joa.en}. ¶ It is recorded in Grobiņa in 1598; the pair Jukums/Joahims has been in the calendar since 1767.`,`Jukums priklauso ${joa.lt}. ¶ Grobinoje Jukums užrašytas 1598 metais; pora Jukums/Joahims kalendoriuje yra nuo 1767 metų.`,`Jukums kuulub ${joa.et}. ¶ Grobiņas on Jukums kirja pandud 1598. aastal; nimepaar Jukums/Joahims on kalendris alates 1767. aastast.`),
  Jovita:E(`Jovita pieder latīņu Jupitera vārdu saimei: Iuppiter, ģenitīvā Iovis, ar -itus → Iovitus. ¶ Saldus rajonā vārds pierakstīts 20. gadsimta trešajā ceturksnī, kalendārā tas ir kopš 1903. gada.`,`Jovita относится к латинской семье имени Юпитер: Iuppiter, род. п. Iovis, с -itus → Iovitus. ¶ В Салдусском районе имя записано в третьей четверти XX века, в календаре — с 1903 года.`,`Jovita belongs to the Latin family of Jupiter: Iuppiter, genitive Iovis, with -itus → Iovitus. ¶ It is recorded in Saldus district in the third quarter of the twentieth century and has been in the calendar since 1903.`,`Jovita priklauso lotynų Jupiterio vardų šeimai: Iuppiter, kilm. Iovis, su -itus → Iovitus. ¶ Saldaus rajone vardas užrašytas XX amžiaus trečiajame ketvirtyje, kalendoriuje jis yra nuo 1903 metų.`,`Jovita kuulub ladina Jupiteri nimeperre: Iuppiter, omastav Iovis, liitega -itus → Iovitus. ¶ Saldusi rajoonis on nimi kirja pandud 20. sajandi kolmandal veerandil, kalendris on see alates 1903. aastast.`),
  Volfgangs:E(`Volfgangs cēlies no senaugšvācu wolf — «vilks» — un gangan — «iet». ¶ Ādažos vārds pierakstīts 19. gadsimta pēdējā ceturksnī, kalendārā tas ir kopš 1767. gada.`,`Volfgangs восходит к древневерхненемецким wolf — «волк» — и gangan — «идти». ¶ В Адажи имя записано в последней четверти XIX века, в календаре — с 1767 года.`,`Volfgangs comes from Old High German wolf, “wolf”, and gangan, “to go”. ¶ It is recorded in Ādaži in the last quarter of the nineteenth century and has been in the calendar since 1767.`,`Volfgangs kilęs iš senosios aukštaičių vokiečių wolf – „vilkas“ – ir gangan – „eiti“. ¶ Ādažiuose vardas užrašytas XIX amžiaus paskutiniame ketvirtyje, kalendoriuje jis yra nuo 1767 metų.`,`Volfgangs pärineb vanaülemsaksa sõnadest wolf, „hunt“, ja gangan, „minema“. ¶ Ādažis on nimi kirja pandud 19. sajandi viimasel veerandil, kalendris on see alates 1767. aastast.`),
  Volfrīds:E(`Volfrīds cēlies no senaugšvācu wolf — «vilks» — un fridu — «miers». ¶ Vārds pierakstīts 20. gadsimta pirmajā ceturksnī.`,`Volfrīds восходит к древневерхненемецким wolf — «волк» — и fridu — «мир». ¶ Имя записано в первой четверти XX века.`,`Volfrīds comes from Old High German wolf, “wolf”, and fridu, “peace”. ¶ It is recorded in the first quarter of the twentieth century.`,`Volfrīds kilęs iš senosios aukštaičių vokiečių wolf – „vilkas“ – ir fridu – „taika“. ¶ Vardas užrašytas XX amžiaus pirmajame ketvirtyje.`,`Volfrīds pärineb vanaülemsaksa sõnadest wolf, „hunt“, ja fridu, „rahu“. ¶ Nimi on kirja pandud 20. sajandi esimesel veerandil.`),
  Volfs:E(`Volfs saistīts ar senaugšvācu wolf — «vilks» — un garākiem Volf- vārdiem. ¶ Sakas pagastā vārds pierakstīts 1895. gadā.`,`Volfs связан с древневерхненемецким wolf — «волк» — и более длинными именами на Volf-. ¶ В Сакской волости имя записано в 1895 году.`,`Volfs is linked with Old High German wolf, “wolf”, and with longer Volf- names. ¶ It is recorded in Saka parish in 1895.`,`Volfs siejamas su senosios aukštaičių vokiečių wolf – „vilkas“ – ir ilgesniais Volf- vardais. ¶ Sakos valsčiuje vardas užrašytas 1895 metais.`,`Volfs seostub vanaülemsaksa sõnaga wolf, „hunt“, ja pikemate Volf-nimedega. ¶ Saka vallas on nimi kirja pandud 1895. aastal.`),
  Barba:E(`Barba ir Barbaras forma; tā pieder ${barb.lv}. ¶ Rīgā Barba pierakstīta jau 1475. gadā, kalendārā tā ir kopš 1877. gada.`,`Barba — форма имени Barbara и относится к ${barb.ru}. ¶ В Риге Barba записана уже в 1475 году, в календаре — с 1877 года.`,`Barba is a form of Barbara and belongs to ${barb.en}. ¶ It is recorded in Riga as early as 1475 and has been in the calendar since 1877.`,`Barba – Barboros forma, priklausanti ${barb.lt}. ¶ Rygoje Barba užrašyta jau 1475 metais, kalendoriuje ji yra nuo 1877 metų.`,`Barba on Barbara vorm ja kuulub ${barb.et}. ¶ Riias on Barba kirja pandud juba 1475. aastal, kalendris on see alates 1877. aastast.`),
  Varvara:E(`Varvara ir Barbaras krieviskā forma; tā pieder ${barb.lv}. ¶ Vārds pierakstīts 18. gadsimtā, kalendārā tas ir kopš 1937. gada.`,`Varvara — русская форма имени Barbara и относится к ${barb.ru}. ¶ Имя записано в XVIII веке, в календаре — с 1937 года.`,`Varvara is the Russian form of Barbara and belongs to ${barb.en}. ¶ It is recorded in the eighteenth century and has been in the calendar since 1937.`,`Varvara – rusiška Barboros forma, priklausanti ${barb.lt}. ¶ Vardas užrašytas XVIII amžiuje, kalendoriuje jis yra nuo 1937 metų.`,`Varvara on Barbara vene vorm ja kuulub ${barb.et}. ¶ Nimi on kirja pandud 18. sajandil, kalendris on see alates 1937. aastast.`),
  Vudro:E(`Vudro ir angļu Woodrow latviskā forma. Angļu uzvārds cēlies no vietvārda ar senangļu wudu — «mežs» — un rāw — «rinda»: «māju rinda pie meža» vai «klajums mežā». ¶ Vudro pierakstīts 1932. gadā; ASV vārds Woodrow kļuva populārs prezidenta Vudro Vilsona laikā (1912–1921).`,`Vudro — латышская форма английского Woodrow. Английская фамилия происходит от топонима с древнеанглийскими wudu — «лес» — и rāw — «ряд»: «ряд домов у леса» или «поляна в лесу». ¶ Vudro записан в 1932 году; в США имя Woodrow стало популярным во время президентства Вудро Вильсона (1912–1921).`,`Vudro is the Latvian form of English Woodrow. The English surname comes from a place name with Old English wudu, “wood”, and rāw, “row”: “a row of houses by a wood” or “a clearing in the forest”. ¶ It is recorded in 1932; in the United States Woodrow became popular during Woodrow Wilson’s candidacy and presidency (1912–1921).`,`Vudro – latviška angliško Woodrow forma. Angliška pavardė kilusi iš vietovardžio su senosios anglų wudu – „miškas“ – ir rāw – „eilė“: „namų eilė prie miško“ arba „proskyna miške“. ¶ Vudro užrašytas 1932 metais; JAV vardas Woodrow išpopuliarėjo prezidento Woodrow Wilsono laikais (1912–1921).`,`Vudro on inglise nime Woodrow läti vorm. Inglise perekonnanimi pärineb kohanimest, milles on vanainglise wudu, „mets“, ja rāw, „rida“: „majade rida metsa ääres“ või „metsalagendik“. ¶ Vudro on kirja pandud 1932. aastal; USA-s sai Woodrow populaarseks Woodrow Wilsoni kandideerimise ja presidendiaja (1912–1921) ajal.`),
  Sabīne:E(`${sab.lv} ¶ Sabīna un Sabīne Ķirupē pierakstītas 1761. gadā, kalendārā tās ir kopš 1767. gada.`,`${sab.ru} ¶ Sabīna и Sabīne записаны в Кирупе в 1761 году, в календаре — с 1767 года.`,`${sab.en} ¶ Sabīna and Sabīne are recorded in Ķirupe in 1761 and have been in the calendar since 1767.`,`${sab.lt} ¶ Sabīna ir Sabīne užrašytos Ķirupėje 1761 metais, kalendoriuje jos yra nuo 1767 metų.`,`${sab.et} ¶ Sabīna ja Sabīne on kirja pandud Ķirupes 1761. aastal, kalendris on need alates 1767. aastast.`),
  Sabīna:E(`${sab.lv} ¶ Sabīna un Sabīne Ķirupē pierakstītas 1761. gadā, kalendārā tās ir kopš 1767. gada.`,`${sab.ru} ¶ Sabīna и Sabīne записаны в Кирупе в 1761 году, в календаре — с 1767 года.`,`${sab.en} ¶ Sabīna and Sabīne are recorded in Ķirupe in 1761 and have been in the calendar since 1767.`,`${sab.lt} ¶ Sabīna ir Sabīne užrašytos Ķirupėje 1761 metais, kalendoriuje jos yra nuo 1767 metų.`,`${sab.et} ¶ Sabīna ja Sabīne on kirja pandud Ķirupes 1761. aastal, kalendris on need alates 1767. aastast.`),
  Sabrina:E(`${sabr.lv} ¶ Angļu Sabrina latviski oficiāli atveido kā Sabrina.`,`${sabr.ru} ¶ Английское Sabrina официально передаётся по-латышски как Sabrina.`,`${sabr.en} ¶ English Sabrina is officially rendered in Latvian as Sabrina.`,`${sabr.lt} ¶ Angliškas Sabrina oficialiai latviškai perteikiamas kaip Sabrina.`,`${sabr.et} ¶ Inglise Sabrina antakse läti keeles ametlikult edasi kujul Sabrina.`),
  Sabrīna:E(`${sabr.lv} ¶ Angļu Sabrina latviski oficiāli atveido arī kā Sabrīna.`,`${sabr.ru} ¶ Английское Sabrina официально передаётся по-латышски и как Sabrīna.`,`${sabr.en} ¶ English Sabrina is also officially rendered in Latvian as Sabrīna.`,`${sabr.lt} ¶ Angliškas Sabrina oficialiai latviškai perteikiamas ir kaip Sabrīna.`,`${sabr.et} ¶ Inglise Sabrina antakse läti keeles ametlikult edasi ka kujul Sabrīna.`),
  Sarma:E(`Sarma cēlusies no latviešu sarma — balti ledus kristāliņi uz virsmām. ¶ Vārds pierakstīts jau 1507. gadā, kalendārā tas ir kopš 1908. gada.`,`Sarma происходит от латышского sarma — «иней», белые ледяные кристаллики на поверхностях. ¶ Имя записано уже в 1507 году, в календаре — с 1908 года.`,`Sarma comes from Latvian sarma, “hoarfrost”, white ice crystals on surfaces. ¶ It is recorded as early as 1507 and has been in the calendar since 1908.`,`Sarma kilusi iš latvių sarma – „šerkšnas“, balti ledo kristalėliai ant paviršių. ¶ Vardas užrašytas jau 1507 metais, kalendoriuje jis yra nuo 1908 metų.`,`Sarma tuleb läti sõnast sarma, „hall, härmatis“ – valged jääkristallid pindadel. ¶ Nimi on kirja pandud juba 1507. aastal, kalendris on see alates 1908. aastast.`),
  Klaudijs:E(`Klaudijs ir romiešu dzimtas vārda Claudius latviskā forma; vārdu mēdz saistīt ar latīņu claudus — «klibs», taču šī saikne nav droša. ¶ Pie Aizputes Klaudijs pierakstīts 19. gadsimta pēdējā ceturksnī, kalendārā tas ir kopš 1767. gada.`,`Klaudijs — латышская форма римского родового имени Claudius; его связывают с латинским claudus — «хромой», но эта связь ненадёжна. ¶ Под Айзпуте Klaudijs записан в последней четверти XIX века, в календаре — с 1767 года.`,`Klaudijs is the Latvian form of the Roman family name Claudius; it is sometimes linked with Latin claudus, “lame”, but that link is uncertain. ¶ It is recorded near Aizpute in the last quarter of the nineteenth century and has been in the calendar since 1767.`,`Klaudijs – latviška romėnų giminės vardo Claudius forma; jis kartais siejamas su lotynų claudus – „šlubas“, tačiau šis ryšys nepatikimas. ¶ Prie Aizputės Klaudijs užrašytas XIX amžiaus paskutiniame ketvirtyje, kalendoriuje jis yra nuo 1767 metų.`,`Klaudijs on Rooma suguvõsanime Claudius läti vorm; seda seostatakse mõnikord ladina sõnaga claudus, „lombakas“, kuid see seos pole kindel. ¶ Aizpute lähedal on Klaudijs kirja pandud 19. sajandi viimasel veerandil, kalendris on see alates 1767. aastast.`),
  Nika:E(`Nika ir gan sieviešu, gan vīriešu vārds. To var saistīt tieši ar grieķu nikē — «uzvara» — vai uzskatīt par Nikolaja īsformu. ¶ Vīriešu vārds Nika Irbē pierakstīts 1857. gadā, kalendārā tas ir kopš 1889. gada; sieviešu Nika pierakstīta 1969. un 1973. gadā. Horvātu sieviešu vārdu Nika latviski atveido kā Nika.`,`Nika — и женское, и мужское имя. Его можно связать прямо с греческим nikē — «победа» — или считать краткой формой имени Nikolajs. ¶ Мужское Nika записано в Ирбе в 1857 году, в календаре — с 1889 года; женское Nika записано в 1969 и 1973 годах. Хорватское женское имя Nika по-латышски передаётся как Nika.`,`Nika is both a feminine and a masculine name. It can be linked directly with Greek nikē, “victory”, or seen as a short form of Nikolajs. ¶ Masculine Nika is recorded in Irbe in 1857 and has been in the calendar since 1889; feminine Nika is recorded in 1969 and 1973. Croatian feminine Nika is rendered in Latvian as Nika.`,`Nika – ir moteriškas, ir vyriškas vardas. Jį galima tiesiogiai sieti su graikų nikē – „pergalė“ – arba laikyti vardo Nikolajs trumpiniu. ¶ Vyriškas Nika Irbėje užrašytas 1857 metais, kalendoriuje jis yra nuo 1889 metų; moteriškas Nika užrašytas 1969 ir 1973 metais. Kroatiškas moteriškas vardas Nika latviškai perteikiamas kaip Nika.`,`Nika on nii nais- kui ka mehenimi. Seda võib seostada otse kreeka sõnaga nikē, „võit“, või pidada nime Nikolajs lühikujuks. ¶ Mehenimi Nika on kirja pandud Irbes 1857. aastal ja kalendris alates 1889. aastast; naisenimi Nika on kirja pandud 1969. ja 1973. aastal. Horvaadi naisenimi Nika antakse läti keeles edasi kujul Nika.`),
  Nikandrs:E(`Nikandrs ir krievu Никандр latviskā forma; tas cēlies no grieķu Nikandros: nikē — «uzvara» — un anēr (ģenitīvā andros) — «vīrs». Ar Nikolaju tam kopīgs tikai sākums.`,`Nikandrs — латышская форма русского Никандр; оно восходит к греческому Nikandros: nikē — «победа» — и anēr (род. п. andros) — «муж». С Николаем у него общее только начало.`,`Nikandrs is the Latvian form of Russian Nikandr, from Greek Nikandros: nikē, “victory”, and anēr (genitive andros), “man”. It shares only its beginning with Nikolaos.`,`Nikandrs – latviška rusiško Никандр forma, kilusi iš graikų Nikandros: nikē – „pergalė“ – ir anēr (kilm. andros) – „vyras“. Su Mikalojumi jį sieja tik pradžia.`,`Nikandrs on vene nime Никандр läti vorm kreeka nimest Nikandros: nikē, „võit“, ja anēr (omastav andros), „mees“. Nikolaosega on tal ühine ainult algus.`),
  Niklass:E(`${nik.lv} ¶ Niklass ir Nicklas latviskā forma; kalendārā tas ir kopš 1817. gada.`,`${nik.ru} ¶ Niklass — латышская форма Nicklas; в календаре — с 1817 года.`,`${nik.en} ¶ Niklass is the Latvian form of Nicklas and has been in the calendar since 1817.`,`${nik.lt} ¶ Niklass – latviška Nicklas forma; kalendoriuje jis yra nuo 1817 metų.`,`${nik.et} ¶ Niklass on nime Nicklas läti vorm; kalendris on see alates 1817. aastast.`)
 },
 lt:{
  Aurelija:E(`Aurelija ir latīņu Aurelius/Aurelia saimes lietuviešu sieviešu forma; vārdu saista ar aureus — «zelta». ¶ ${lt64('Aurelija',o15,'Aura').lv}`,`Aurelija — литовская женская форма семьи латинских Aurelius/Aurelia; имя связывают с aureus — «золотой». ¶ ${lt64('Aurelija',o15,'Aura').ru}`,`Aurelija is the Lithuanian feminine form of Latin Aurelius/Aurelia, a name associated with aureus, “golden”. ¶ ${lt64('Aurelija',o15,'Aura').en}`,`Aurelija – lietuviška moteriška lotynų Aurelius/Aurelia šeimos forma; vardas siejamas su aureus – „auksinis“. ¶ ${lt64('Aurelija',o15,'Aura').lt}`,`Aurelija on ladina Aurelius/Aurelia nimepere leedu naisvorm; nime seostatakse sõnaga aureus, „kuldne“. ¶ ${lt64('Aurelija',o15,'Aura').et}`),
  Liucijus:E(`Liucijus ir latīņu Lucius lietuviešu forma; tradicionāli to saista ar lux (ģenitīvā lucis) — «gaisma». ¶ ${lt64('Liucijus',m4,'Liucas').lv}`,`Liucijus — литовская форма латинского Lucius; традиционно его связывают с lux (род. п. lucis) — «свет». ¶ ${lt64('Liucijus',m4,'Liucas').ru}`,`Liucijus is the Lithuanian form of Latin Lucius, traditionally linked with lux (genitive lucis), “light”. ¶ ${lt64('Liucijus',m4,'Liucas').en}`,`Liucijus – lietuviška lotynų Lucius forma; tradiciškai jis siejamas su lux (kilm. lucis) – „šviesa“. ¶ ${lt64('Liucijus',m4,'Liucas').lt}`,`Liucijus on ladina nime Lucius leedu vorm, mida seostatakse traditsiooniliselt sõnaga lux (omastav lucis), „valgus“. ¶ ${lt64('Liucijus',m4,'Liucas').et}`),
  Milmantė:E(`Milmantė ir lietuviešu divcelmu sieviešu vārds: mil- saistīts ar (pa)milti — «iemīlēt», bet mant- ar mantus — «sapratīgs» — un manta — «manta». Vīriešu Milmantas pieskaitāms prūšu vārdiem.`,`Milmantė — литовское женское двухосновное имя: mil- связано с (pa)milti — «полюбить», а mant- — с mantus — «толковый» — и manta — «имущество». Мужское Milmantas относят к прусским именам.`,`Milmantė is a Lithuanian two-stem feminine name: mil- relates to (pa)milti, “to come to love”, and mant- to mantus, “capable”, and manta, “property”. The masculine Milmantas is counted among Prussian names.`,`Milmantė – lietuviškas dvikamienis moteriškas vardas: mil- susijęs su (pa)milti, o mant- – su mantus ir manta. Vyriškas Milmantas priskiriamas prūsų vardams.`,`Milmantė on leedu kahetüveline naisenimi: mil- seostub sõnaga (pa)milti, „armuma“, ja mant- sõnadega mantus, „taibukas“, ning manta, „vara“. Mehenimi Milmantas loetakse preisi nimede hulka.`),
  Paulina:E(`Paulina pieder latīņu Paulus, Paulinus un Paulina saimei; paulus nozīmē «mazs». ¶ ${lt64('Paulina',j6,'Paulė').lv}`,`Paulina относится к семье латинских Paulus, Paulinus и Paulina; paulus значит «малый». ¶ ${lt64('Paulina',j6,'Paulė').ru}`,`Paulina belongs to the Latin family of Paulus, Paulinus and Paulina; paulus means “small”. ¶ ${lt64('Paulina',j6,'Paulė').en}`,`Paulina priklauso lotynų Paulus, Paulinus ir Paulina šeimai; paulus reiškia „mažas“. ¶ ${lt64('Paulina',j6,'Paulė').lt}`,`Paulina kuulub ladina nimede Paulus, Paulinus ja Paulina perre; paulus tähendab „väike“. ¶ ${lt64('Paulina',j6,'Paulė').et}`),
  Svirgailas:E(`Svirgailas ir lietuviešu divcelmu vārds ar variantu Svirgaila un īsformām Sviras un Svirius. Gail- salīdzina ar gailas — «stiprs, sparīgs»; svir- skaidrojumi atšķiras. ¶ 1964. gada lietuviešu vārdu kalendārā forma Svirgaila ierakstīta 2. decembrī ar īsformu Sviras.`,`Svirgailas — литовское двухосновное имя с вариантом Svirgaila и краткими формами Sviras и Svirius. Gail- сравнивают с gailas — «сильный, бодрый»; объяснения svir- расходятся. ¶ В литовском календаре имён 1964 года форма Svirgaila записана на 2 декабря с краткой формой Sviras.`,`Svirgailas is a Lithuanian two-stem name with the variant Svirgaila and the short forms Sviras and Svirius. Gail- is compared with gailas, “strong, vigorous”; explanations of svir- differ. ¶ The Lithuanian name calendar of 1964 lists the form Svirgaila on 2 December, with the short form Sviras.`,`Svirgailas – lietuviškas dvikamienis vardas su variantu Svirgaila ir trumpiniais Sviras bei Svirius. Gail- lyginamas su gailas; svir- aiškinimai skiriasi. ¶ 1964 metų lietuvių vardų kalendoriuje forma Svirgaila įrašyta gruodžio 2 dieną su trumpiniu Sviras.`,`Svirgailas on leedu kahetüveline nimi, mille variant on Svirgaila ning lühikujud Sviras ja Svirius. Gail- võrreldakse sõnaga gailas, „tugev, jõuline“; svir- seletused lähevad lahku. ¶ 1964. aasta leedu nimekalendris on kuju Svirgaila 2. detsembril lühikujuga Sviras.`),
  Ksaveras:E(`Ksaveras pieder Ksavera (Xavier) saimei; tās pamatā ir basku vietvārds Etxaberri: etxe — «māja» — un berri — «jauns». ¶ 1964. gada lietuviešu vārdu kalendārā Pranciškus Ksaveras ierakstīts 3. decembrī ar īsformām Pranas un Pranys.`,`Ksaveras относится к семье имени Ксаверий (Xavier); в его основе — баскский топоним Etxaberri: etxe — «дом» — и berri — «новый». ¶ В литовском календаре имён 1964 года Pranciškus Ksaveras записан на 3 декабря с краткими формами Pranas и Pranys.`,`Ksaveras belongs to the Xavier family, based on the Basque place name Etxaberri: etxe, “house”, and berri, “new”. ¶ The Lithuanian name calendar of 1964 lists Pranciškus Ksaveras on 3 December, with the short forms Pranas and Pranys.`,`Ksaveras priklauso Ksavero (Xavier) šeimai; jos pagrindas – baskų vietovardis Etxaberri: etxe – „namas“ – ir berri – „naujas“. ¶ 1964 metų lietuvių vardų kalendoriuje Pranciškus Ksaveras įrašytas gruodžio 3 dieną su trumpiniais Pranas ir Pranys.`,`Ksaveras kuulub Xavieri nimeperre, mille aluseks on baski kohanimi Etxaberri: etxe, „maja“, ja berri, „uus“. ¶ 1964. aasta leedu nimekalendris on Pranciškus Ksaveras 3. detsembril lühikujudega Pranas ja Pranys.`),
  Atalija:E(`Atalija ir Bībeles Atalijas, Jūdas ķēniņienes, vārds lietuviski; ebreju vārds, iespējams, nozīmē «Jahve ir paaugstināts». ¶ Atalija valdīja Jūdā ap 842./841.–834. gadu p. m. ē.; viņas stāstu atveido Žana Rasīna traģēdija «Atalija» (1691). 1964. gada lietuviešu vārdu kalendārā Atalija ierakstīta 3. decembrī.`,`Atalija — литовская форма имени библейской Гофолии (Athaliah), царицы Иудеи; еврейское имя, возможно, значит «Яхве возвышен». ¶ Гофолия правила Иудеей около 842/841–834 годов до н. э.; её история легла в основу трагедии Жана Расина «Гофолия» (1691). В литовском календаре имён 1964 года Atalija записана на 3 декабря.`,`Atalija is the Lithuanian name of the biblical Athaliah, queen of Judah; the Hebrew name possibly means “Yahweh is exalted”. ¶ Athaliah ruled Judah in about 842/841–834 BC, and her story is told in Jean Racine’s tragedy Athalie (1691). The Lithuanian name calendar of 1964 lists Atalija on 3 December.`,`Atalija – biblinės Judo karalienės Atalijos vardas; hebrajiškas vardas galbūt reiškia „Jahvė išaukštintas“. ¶ Atalija valdė Judą apie 842/841–834 metus pr. Kr.; jos istorija papasakota Jeano Racine’o tragedijoje „Atalija“ (1691). 1964 metų lietuvių vardų kalendoriuje Atalija įrašyta gruodžio 3 dieną.`,`Atalija on piibliliku Juuda kuninganna Atalja nimi leedu keeles; heebrea nimi tähendab arvatavasti „Jahve on ülendatud“. ¶ Atalja valitses Juudat umbes 842/841–834 eKr. ning tema lugu jutustab Jean Racine’i tragöödia „Athalie“ (1691). 1964. aasta leedu nimekalendris on Atalija 3. detsembril.`),
  Osmundas:E(`Osmundas pieder Osmunda saimei: senangļu ōs un senskandināvu áss/óss nozīmē «dievs», bet mund/mundr — «aizstāvis». ¶ Latīņu Osmundus pierakstīts Anglijā 1189. gadā.`,`Osmundas относится к семье имени Осмунд: древнеанглийское ōs и древнескандинавское áss/óss значат «бог», а mund/mundr — «защитник». ¶ Латинское Osmundus записано в Англии в 1189 году.`,`Osmundas belongs to the Osmund family: Old English ōs and Old Norse áss/óss mean “god”, and mund/mundr means “protector”. ¶ Latin Osmundus is recorded in England in 1189.`,`Osmundas priklauso Osmundo šeimai: senosios anglų ōs ir senosios skandinavų áss/óss reiškia „dievas“, o mund/mundr – „gynėjas“. ¶ Lotyniškas Osmundus užrašytas Anglijoje 1189 metais.`,`Osmundas kuulub Osmundi nimeperre: vanainglise ōs ja vanapõhja áss/óss tähendavad „jumal“ ning mund/mundr „kaitsja“. ¶ Ladina Osmundus on kirja pandud Inglismaal 1189. aastal.`),
  Vainotas:E(`Vainotas ir vienkāršs atvasinājums no vārda elementa vain-, ko saista ar lietuviešu vainà — «vaina, cēlonis». ¶ ${lt64('Vainotas',d4,'Vainas').lv}`,`Vainotas — простое производное от элемента имени vain-, который связывают с литовским vainà — «вина, причина». ¶ ${lt64('Vainotas',d4,'Vainas').ru}`,`Vainotas is a simple derivative of the name element vain-, linked with Lithuanian vainà, “fault, blame, cause”. ¶ ${lt64('Vainotas',d4,'Vainas').en}`,`Vainotas – paprastas vardo elemento vain- vedinys; jis siejamas su žodžiu vainà. ¶ ${lt64('Vainotas',d4,'Vainas').lt}`,`Vainotas on nimeosast vain- moodustatud lihtne tuletis; seda seostatakse leedu sõnaga vainà, „süü, põhjus“. ¶ ${lt64('Vainotas',d4,'Vainas').et}`),
  Eimintas:E(`Eimintas ir lietuviešu divcelmu vārds: ei- no eiti — «iet», bet mint- no minti, mintis — «domāt, doma». Tas ir 20. gadsimtā darināts un lietošanā ieviests vārds.`,`Eimintas — литовское двухосновное имя: ei- от eiti — «идти», а mint- от minti, mintis — «думать, мысль». Это имя, созданное и вошедшее в употребление в XX веке.`,`Eimintas is a Lithuanian two-stem name: ei- from eiti, “to go”, and mint- from minti, mintis, “to think, thought”. It is a name formed and brought into use in the twentieth century.`,`Eimintas – lietuviškas dvikamienis vardas: ei- iš eiti, o mint- iš minti, mintis. Tai XX amžiuje sukurtas ir į vartoseną įvestas vardas.`,`Eimintas on leedu kahetüveline nimi: ei- sõnast eiti, „minema“, ja mint- sõnadest minti, mintis, „mõtlema, mõte“. See on 20. sajandil loodud ja kasutusele võetud nimi.`),
  Gracija:E(`Gracija pieder Gracia/Gratia vārdu grupai: tuvākā izcelsme ir spāņu gracia — «žēlastība, grācija», senākais pamats — latīņu gratia. ¶ Radniecīgais latīņu Gracia pierakstīts Francijā 1287. gadā.`,`Gracija относится к группе Gracia/Gratia: ближайший прообраз — испанское gracia — «благодать, грация», более древняя основа — латинское gratia. ¶ Родственное латинское Gracia записано во Франции в 1287 году.`,`Gracija belongs to the Gracia/Gratia group: the immediate source is Spanish gracia, “grace”, the older base Latin gratia. ¶ Related Latin Gracia is recorded in France in 1287.`,`Gracija priklauso Gracia/Gratia grupei: artimiausia kilmė – ispanų gracia, „malonė, grakštumas“, senesnis pagrindas – lotynų gratia. ¶ Giminingas lotyniškas Gracia užrašytas Prancūzijoje 1287 metais.`,`Gracija kuulub nimerühma Gracia/Gratia: vahetu eeskuju on hispaania gracia, „arm, graatsia“, vanem alus ladina gratia. ¶ Seotud ladina Gracia on kirja pandud Prantsusmaal 1287. aastal.`),
  Gratas:E(`Gratas cēlies no latīņu gratus — «patīkams, gaidīts». ¶ ${lt64('Gratas',d5).lv}`,`Gratas восходит к латинскому gratus — «приятный, желанный». ¶ ${lt64('Gratas',d5).ru}`,`Gratas comes from Latin gratus, “pleasing, welcome”. ¶ ${lt64('Gratas',d5).en}`,`Gratas kilęs iš lotynų gratus – „malonus, laukiamas“. ¶ ${lt64('Gratas',d5).lt}`,`Gratas pärineb ladina sõnast gratus, „meeldiv, teretulnud“. ¶ ${lt64('Gratas',d5).et}`),
  Svaigaudas:E(`Svaigaudas ir senprūšu personvārds: pirmo daļu saista ar prūšu swais — «savs», otro gaud- ar lietuviešu gauti — «iegūt».`,`Svaigaudas — древнепрусское личное имя: первую часть связывают с прусским swais — «свой», вторую, gaud-, — с литовским gauti — «получать».`,`Svaigaudas is an Old Prussian personal name: the first part is linked with Prussian swais, “own”, the second, gaud-, with Lithuanian gauti, “to get”.`,`Svaigaudas – senovės prūsų asmenvardis: pirmoji dalis siejama su prūsų swais – „savas“, antroji, gaud-, – su lietuvių gauti.`,`Svaigaudas on vanapreisi isikunimi: esimest osa seostatakse preisi sõnaga swais, „oma“, teist, gaud-, leedu sõnaga gauti, „saama“.`)
 },
 ee:{
  Aira:E(`Aira ir somu vārda Airi variants; Airi skaidro ar airut — «sūtnis, vēstnesis», iespējams, ar vietvārdu ietekmi. ¶ 1929. gada igauņu vārdu krājumā Aira dota sieviešu vārdu sarakstā kā somu vārds.`,`Aira — вариант финского имени Airi; Airi объясняют через airut — «посланец, вестник», возможно, с влиянием топонимов. ¶ В эстонском собрании имён 1929 года Aira дана среди женских имён как финское имя.`,`Aira is a variant of Finnish Airi, which is explained through airut, “messenger, herald”, perhaps with influence from place names. ¶ An Estonian name collection of 1929 lists Aira among women’s names as a Finnish name.`,`Aira – suomiško vardo Airi variantas; Airi aiškinamas per airut – „pasiuntinys, šauklys“, galbūt veikiant vietovardžiams. ¶ 1929 metų estų vardų rinkinyje Aira pateikta tarp moterų vardų kaip suomiškas vardas.`,`Aira on soome nime Airi variant; Airit seletatakse sõnaga airut, „käskjalg, kuulutaja“, võib-olla kohanimede mõjul. ¶ 1929. aasta eesti nimekogus on Aira naisenimede hulgas soome nimena.`),
  Airi:E(`Airi ir somu vārds, ko skaidro ar airut — «sūtnis, vēstnesis»; iespējama arī līdzīgi skanošu vietvārdu ietekme. ¶ 1929. gada igauņu vārdu krājumā Airi dota sieviešu vārdu sarakstā kā somu vārds.`,`Airi — финское имя, которое объясняют через airut — «посланец, вестник»; возможно и влияние созвучных топонимов. ¶ В эстонском собрании имён 1929 года Airi дана среди женских имён как финское имя.`,`Airi is a Finnish name explained through airut, “messenger, herald”; place names with similar sounds may also have played a part. ¶ An Estonian name collection of 1929 lists Airi among women’s names as a Finnish name.`,`Airi – suomiškas vardas, aiškinamas per airut – „pasiuntinys, šauklys“; galbūt prisidėjo ir panašiai skambantys vietovardžiai. ¶ 1929 metų estų vardų rinkinyje Airi pateikta tarp moterų vardų kaip suomiškas vardas.`,`Airi on soome nimi, mida seletatakse sõnaga airut, „käskjalg, kuulutaja“; oma osa võisid olla ka sarnase kõlaga kohanimedel. ¶ 1929. aasta eesti nimekogus on Airi naisenimede hulgas soome nimena.`),
  Leiger:E(`Leiger 1929. gadā ierosināts kā jauns igauņu vīriešu vārds; to saista ar vārdu leiger — «liels, spēcīgs vīrs, milzis» — un ar milzi Leigeru igauņu mitoloģijā. Vārda tālākā cilme nav noskaidrota; tā saistība ar zviedru lekare — «spēlmanis» — ir tikai minējums. ¶ 2005. gadā viena igauņu vietējā avīze Leigeru sauca par hījumaiešu varoni.`,`Leiger в 1929 году предложено как новое эстонское мужское имя; его связывают со словом leiger — «большой сильный человек, великан» — и с великаном Лейгером эстонской мифологии. Дальнейшее происхождение слова не выяснено; связь со шведским lekare — «музыкант, игрец» — лишь предположение. ¶ В 2005 году одна эстонская местная газета назвала Лейгера героем жителей Хийумаа.`,`Leiger was proposed in 1929 as a new Estonian man’s name, linked with the word leiger, “big strong man, giant”, and with the giant Leiger of Estonian mythology. The word’s deeper origin is unclear; a link with Swedish lekare, “player, musician”, is only a guess. ¶ In 2005 an Estonian local newspaper called Leiger a hero of the people of Hiiumaa.`,`Leiger 1929 metais pasiūlytas kaip naujas estiškas vyriškas vardas; jis siejamas su žodžiu leiger – „didelis stiprus vyras, milžinas“ – ir su milžinu Leigeriu estų mitologijoje. Tolesnė žodžio kilmė neaiški; sąsaja su švedų lekare – „muzikantas“ – tik spėjimas. ¶ 2005 metais vienas estų vietinis laikraštis Leigerį pavadino Hiumos žmonių didvyriu.`,`Leigerit pakuti 1929. aastal uue eesti mehenimena; seda seostatakse sõnaga leiger, „suur tugev mees, hiiglane“, ja eesti mütoloogia hiiu Leigeriga. Sõna kaugem päritolu pole selge; seos rootsi sõnaga lekare, „pillimees“, on vaid oletus. ¶ 2005. aastal nimetas üks eesti kohalik ajaleht Leigerit hiidlaste kangelaseks.`),
  Leino:E(`Leino saista ar igauņu lein — «sēras».`,`Leino связывают с эстонским lein — «скорбь, траур».`,`Leino is linked with Estonian lein, “mourning”.`,`Leino siejamas su estų lein – „gedulas“.`,`Leino seostub sõnaga lein.`),
  Barba:E(`Barba ir Barbaras forma; tā pieder ${barb.lv}. ¶ Latvijā Barba pierakstīta Rīgā jau 1475. gadā.`,`Barba — форма имени Barbara и относится к ${barb.ru}. ¶ В Латвии Barba записана в Риге уже в 1475 году.`,`Barba is a form of Barbara and belongs to ${barb.en}. ¶ In Latvia Barba is recorded in Riga as early as 1475.`,`Barba – Barboros forma, priklausanti ${barb.lt}. ¶ Latvijoje Barba užrašyta Rygoje jau 1475 metais.`,`Barba on Barbara vorm ja kuulub ${barb.et}. ¶ Lätis on Barba kirja pandud Riias juba 1475. aastal.`),
  Varve:E(`Varve pieder ${barb.lv}.`,`Varve относится к ${barb.ru}.`,`Varve belongs to ${barb.en}.`,`Varve priklauso ${barb.lt}.`,`Varve kuulub ${barb.et}.`),
  Selma:E(`Selmas nozīme nav zināma: tā var būt Anselmas īsforma vai radusies Džeimsa Makfersona Osiāna dzejoļu iespaidā, kur Selma ir pils nosaukums. ¶ Osiāna dzejoļi iznāca 1761.–1763. gadā, un Vācijā Selmu kā vārdu sāka lietot 18. gadsimta beigās.`,`Значение Selma неизвестно: это может быть краткая форма имени Anselma или имя, навеянное поэмами Оссиана Джеймса Макферсона, где Сельма — название замка. ¶ Поэмы Оссиана вышли в 1761–1763 годах, а в Германии Selma стали давать как имя с конца XVIII века.`,`The meaning of Selma is not known: it may be a short form of Anselma, or it may come from James Macpherson’s Ossian poems, where Selma is the name of a castle. ¶ The Ossian poems were published in 1761–1763, and Selma came into use as a given name in Germany from the late eighteenth century.`,`Selmos reikšmė nežinoma: tai gali būti Anselmos trumpinys arba vardas, įkvėptas Jameso Macphersono Osiano poemų, kuriose Selma – pilies pavadinimas. ¶ Osiano poemos išėjo 1761–1763 metais, o Vokietijoje Selma kaip vardas pradėtas duoti XVIII amžiaus pabaigoje.`,`Selma tähendus pole teada: see võib olla Anselma lühikuju või pärineda James Macphersoni Ossiani lauludest, kus Selma on lossi nimi. ¶ Ossiani laulud ilmusid 1761–1763 ning Saksamaal hakati Selmat eesnimena kasutama 18. sajandi lõpust.`),
  Nigulas:E(`${nik.lv} ¶ 1929. gada igauņu vārdu krājumā Nigulas dots Nikolaus saimē.`,`${nik.ru} ¶ В эстонском собрании имён 1929 года Nigulas дан в семье Nikolaus.`,`${nik.en} ¶ An Estonian name collection of 1929 lists Nigulas in the Nikolaus family.`,`${nik.lt} ¶ 1929 metų estų vardų rinkinyje Nigulas pateiktas Nikolaus šeimoje.`,`${nik.et} ¶ 1929. aasta eesti nimekogus on Nigulas Nikolause nimeperes.`),
  Niilas:E(`${nik.lv} Igauņu valodā Niilas ir viena no Nikolaus formām.`,`${nik.ru} В эстонском Niilas — одна из форм имени Nikolaus.`,`${nik.en} In Estonian Niilas is one of the forms of Nikolaus.`,`${nik.lt} Estų kalboje Niilas – viena Nikolaus formų.`,`${nik.et} Eesti keeles on Niilas üks Nikolause vorme.`),
  Niilo:E(`${nik.lv} Igauņu valodā Niilo ir viena no Nikolaus formām.`,`${nik.ru} В эстонском Niilo — одна из форм имени Nikolaus.`,`${nik.en} In Estonian Niilo is one of the forms of Nikolaus.`,`${nik.lt} Estų kalboje Niilo – viena Nikolaus formų.`,`${nik.et} Eesti keeles on Niilo üks Nikolause vorme.`),
  Nils:E(`${nik.lv} Igauņu Nils saistīts ar zviedru Nils. ¶ Zviedru Nils pierakstīts jau 1543. gadā.`,`${nik.ru} Эстонское Nils связано со шведским Nils. ¶ Шведское Nils записано уже в 1543 году.`,`${nik.en} Estonian Nils is linked with Swedish Nils. ¶ Swedish Nils is recorded as early as 1543.`,`${nik.lt} Estiškas Nils siejamas su švedišku Nils. ¶ Švediškas Nils užrašytas jau 1543 metais.`,`${nik.et} Eesti Nils seostub rootsi Nilsiga. ¶ Rootsi Nils on kirja pandud juba 1543. aastal.`),
  Laas:E(`${nik.lv} ¶ 1929. gada igauņu vārdu krājumā Laas pielīdzināts vārdam Klaus.`,`${nik.ru} ¶ В эстонском собрании имён 1929 года Laas приравнен к Klaus.`,`${nik.en} ¶ An Estonian name collection of 1929 equates Laas with Klaus.`,`${nik.lt} ¶ 1929 metų estų vardų rinkinyje Laas prilygintas vardui Klaus.`,`${nik.et} ¶ 1929. aasta eesti nimekogus on Laas võrdsustatud nimega Klaus.`)
 }
};
